  });

const makeRequestLayer = (body: unknown, adminKey?: string) => {
  const headers =
    adminKey === undefined ? undefined : { 'x-admin-key': adminKey };

  const request = HttpServerRequest.fromWeb(
    new Request('http://example.com/api/admin/webhooks/register', {
