  const params = new URL(url).searchParams;
  const record: Record<string, string | Array<string>> = {};
  for (const [key, value] of params.entries()) {
    const existing = record[key];
    if (existing === undefined) {
      record[key] = value;
    } else if (Array.isArray(existing)) {
      existing.push(value);
    } else {
